// {{{ Intent
// Keep every located Immich photo and video in an album for its city. The
// first successful execution scans the whole library. Later executions scan
// three days of uploads, and a weekly full scan catches delayed metadata and
// repairs anything missed during an outage.
//
// Album membership is additive. Re-running this node is safe: Immich reports
// an existing album membership as a duplicate, which counts as success here.
// }}}

const API = $env.IMMICH_URL ?? 'http://127.0.0.1:8416';
const API_KEY = $env.IMMICH_API_KEY;
const FULL_SCAN_AFTER_MS = 7 * 24 * 60 * 60 * 1000;
const RECENT_WINDOW_MS = 3 * 24 * 60 * 60 * 1000;
const PAGE_SIZE = 1000;
const ADD_BATCH_SIZE = 500;
const MARKER = 'yomiLocationAlbum';

if (!API_KEY) throw new Error('IMMICH_API_KEY is not configured');

const request = async (method, path, body) =>
  await this.helpers.httpRequest({
    method,
    url: `${API}${path}`,
    headers: {'x-api-key': API_KEY},
    body,
    json: true,
    timeout: 120000,
  });

const locationKey = (city, country) => `${city.toLocaleLowerCase()}\u0000${country.toLocaleLowerCase()}`;
const cityKey = (city) => city.toLocaleLowerCase();
const descriptionFor = (city, country) =>
  `Managed by n8n from Immich location metadata.\n${JSON.stringify({[MARKER]: 1, city, country})}`;

const managedLocation = (album) => {
  const line = String(album.description ?? '')
    .split('\n')
    .find((candidate) => candidate.includes(`"${MARKER}"`));
  if (!line) return null;

  try {
    const value = JSON.parse(line);
    if (value?.[MARKER] !== 1 || !value.city || !value.country) return null;
    return {city: String(value.city).trim(), country: String(value.country).trim()};
  } catch {
    return null;
  }
};

// {{{ Select assets
const state = $getWorkflowStaticData('global');
const now = Date.now();
const lastFullScan = Date.parse(state.lastFullScanAt ?? '');
const fullScan = !Number.isFinite(lastFullScan) || now - lastFullScan >= FULL_SCAN_AFTER_MS;

const assets = [];
let cursor;
do {
  const filter = {city: {ne: null}};
  if (!fullScan) filter.createdAt = {gte: new Date(now - RECENT_WINDOW_MS).toISOString()};

  const response = await request('POST', '/api/search/metadata', {
    withExif: true,
    size: PAGE_SIZE,
    filter,
    ...(cursor ? {cursor} : {}),
  });

  assets.push(...(response?.assets?.items ?? []));
  cursor = response?.assets?.nextCursor ?? null;
} while (cursor);

const byLocation = new Map();
let waitingForLocation = 0;
for (const asset of assets) {
  const city = String(asset.exifInfo?.city ?? '').trim();
  const country = String(asset.exifInfo?.country ?? '').trim();
  if (!city || !country) {
    waitingForLocation += 1;
    continue;
  }

  const key = locationKey(city, country);
  const group = byLocation.get(key) ?? {city, country, assetIds: []};
  group.assetIds.push(asset.id);
  byLocation.set(key, group);
}
// }}}

// {{{ Reconcile albums
const albums = await request('GET', '/api/albums?isOwned=true');
const albumById = new Map(albums.map((album) => [album.id, album]));
const albumsNamed = (name) =>
  [...albumById.values()].filter((album) => album.albumName.toLocaleLowerCase() === name.toLocaleLowerCase());
const managedAlbums = () =>
  [...albumById.values()]
    .map((album) => ({album, location: managedLocation(album)}))
    .filter(({location}) => location);

const countriesByCity = new Map();
for (const group of byLocation.values()) {
  const key = cityKey(group.city);
  const countries = countriesByCity.get(key) ?? new Set();
  countries.add(group.country.toLocaleLowerCase());
  countriesByCity.set(key, countries);
}
for (const {location} of managedAlbums()) {
  const key = cityKey(location.city);
  const countries = countriesByCity.get(key) ?? new Set();
  countries.add(location.country.toLocaleLowerCase());
  countriesByCity.set(key, countries);
}

let albumsCreated = 0;
let albumsRenamed = 0;
let assetsAdded = 0;
let duplicates = 0;

const ensureQualifiedManagedAlbums = async (city) => {
  const entries = managedAlbums().filter(({location}) => cityKey(location.city) === cityKey(city));
  const collision = (countriesByCity.get(cityKey(city))?.size ?? 0) > 1;
  if (!collision) return;

  for (const {album, location} of entries) {
    if (album.albumName.toLocaleLowerCase() !== location.city.toLocaleLowerCase()) continue;
    const qualified = `${location.city}, ${location.country}`;
    await request('PATCH', `/api/albums/${album.id}`, {albumName: qualified});
    album.albumName = qualified;
    albumsRenamed += 1;
  }
};

const sortedGroups = [...byLocation.values()].sort(
  (a, b) => a.city.localeCompare(b.city) || a.country.localeCompare(b.country),
);

for (const group of sortedGroups) {
  await ensureQualifiedManagedAlbums(group.city);

  const managed = managedAlbums().find(
    ({location}) => locationKey(location.city, location.country) === locationKey(group.city, group.country),
  )?.album;
  const collision = (countriesByCity.get(cityKey(group.city))?.size ?? 0) > 1;
  const desiredName = collision ? `${group.city}, ${group.country}` : group.city;
  let album = managed ?? albumsNamed(desiredName)[0];

  if (!album) {
    album = await request('POST', '/api/albums', {
      albumName: desiredName,
      description: descriptionFor(group.city, group.country),
      assetIds: group.assetIds,
    });
    albumById.set(album.id, album);
    albumsCreated += 1;
    assetsAdded += group.assetIds.length;
    continue;
  }

  for (let offset = 0; offset < group.assetIds.length; offset += ADD_BATCH_SIZE) {
    const ids = group.assetIds.slice(offset, offset + ADD_BATCH_SIZE);
    const results = await request('PUT', `/api/albums/${album.id}/assets`, {ids});
    for (const result of results ?? []) {
      if (result.success) assetsAdded += 1;
      else if (result.error === 'duplicate') duplicates += 1;
      else throw new Error(`Immich refused asset ${result.id}: ${result.errorMessage ?? result.error ?? 'unknown error'}`);
    }
  }
}
// }}}

// Save the full-scan checkpoint only after every mutation succeeds. A crash
// repeats the scan and converges through duplicate-safe album additions.
if (fullScan) state.lastFullScanAt = new Date(now).toISOString();
state.lastSuccessfulRunAt = new Date().toISOString();

return [
  {
    json: {
      mode: fullScan ? 'full' : 'recent',
      assetsExamined: assets.length,
      locations: byLocation.size,
      waitingForLocation,
      albumsCreated,
      albumsRenamed,
      assetsAdded,
      alreadySorted: duplicates,
    },
  },
];
